"""Original, expanded teaching for the thirty original Chapter 3 lesson IDs.

Page references are printed pages in the supplied edition (PDF page = printed + 1).
Worked variations are illustrative unless a note explicitly proves a forced reply.
"""
from core.primer_chapter3 import LESSONS

_SPECS = {item['id']: item for item in LESSONS}
GUIDES = {}


def _guide(lesson_id, pages, principles, detail, practice, moves, notes, checks, pitfalls, *, fen=None):
    """Assemble content only; chess legality is checked independently by tests."""
    spec = _SPECS[lesson_id]
    return {
        'pages': pages,
        'goals': tuple('Explain why ' + p[0].lower() + p[1:] for p in principles[:2]),
        'sections': (
            {'title': 'Understand the idea', 'body': spec['explanation']},
            {'title': 'Read the position and calculate', 'body': detail.strip()},
            {'title': 'Practise and transfer', 'body': practice.strip()},
        ),
        'examples': ({'title': spec['title'] + ': a connected worked line',
                      'fen': fen or spec['quiz_fen'], 'moves': tuple(moves), 'notes': tuple(notes)},),
        'pitfalls': tuple(pitfalls),
        'checks': tuple({
            'id': f'{lesson_id}-concept-{i}', 'prompt': q[0],
            'options': (
                {'text': q[1], 'correct': True, 'explanation': q[3]},
                {'text': q[2], 'correct': False, 'explanation': q[4]},
            ),
        } for i, q in enumerate(checks, 1)),
        'recap': tuple(principles),
    }


GUIDES['plan'] = _guide('plan', (57, 60),
    ('A plan connects several useful moves to an aim.', 'The opponent’s replies can require a change of plan.', 'Tactics checks whether a proposed plan works now.'),
    """Start by separating an aim from a move. Developing the kingside pieces and castling is an aim; Nf3 is one way to begin carrying it out. After e4 e5, Nf3 attacks the central pawn and frees g1. Black's Nc6 is a sensible reply because it develops while defending e5. White then brings the bishop to c4, clearing f1 and preparing castling. Black's Nf6 creates a new attack on e4, which White must notice even while following the original plan. Castling improves king safety and rook activity, but it does not remove that central tension. The illustrated sequence contains reasonable choices, not forced moves. A plan guides your search; it must never replace checking the actual threats after each reply.""",
    """Describe the position after every pair of moves using three questions: which pieces are developed, which central pawns are attacked, and can the king castle safely? Then imagine Black had answered Bc4 with d5 instead. You would need to examine the attack on your bishop and centre before repeating a memorized castling move. Practise stating the revised short-term aim in one sentence.""",
    ('Nf3', 'Nc6', 'Bc4', 'Nf6', 'O-O', 'Bc5'),
    ('White wants development and king safety, while watching the centre.', 'The knight develops, attacks e5 and clears g1.', 'Black develops and defends e5; this is a reasonable choice, not the only reply.', 'The bishop becomes active and vacates f1.', 'Black develops and attacks e4, so White must keep that threat in view.', 'White castles legally, linking king safety with rook activation.', 'Black develops the bishop; both players have advanced a coherent opening plan.'),
    (('Which is a plan rather than a single move?', 'Develop the kingside and castle while controlling the centre.', 'Move the knight to f3.', 'The first statement connects several moves to a purpose.', 'Nf3 is a move; its purpose comes from the surrounding plan.'),
     ('What should happen when the opponent creates a serious new threat?', 'Recheck and, when needed, revise the plan.', 'Continue the planned moves regardless.', 'A plan has to work against the actual replies.', 'Ignoring a threat can make an otherwise sensible plan fail.')),
    ('An active-looking move is not automatically useful: name its purpose.', 'A plan is not a rigid move list; every opposing reply deserves a fresh threat check.'))

GUIDES['piece-values'] = _guide('piece-values', (60, 62),
    ('Material values are approximate starting points.', 'A capture is valuable only after checking recaptures.', 'Count the whole exchange, not just the first victim.'),
    """On the diagram the queen can capture either the rook on a7 or the bishop on h4. First trace both routes and inspect the destination squares. Black's king on g8 cannot recapture on a7, and the bishop on h4 does not protect it. The rook is therefore genuinely available. Qxa7 gains about five units; Qxh4 gains about three. This comparison would reverse if taking the rook lost your queen. In the worked line Black moves the bishop rather than recapturing, because no recapture exists. White then brings the queen back towards the centre. Modern beginner values of three for a minor piece and nine for a queen are convenient approximations; the source uses somewhat different numerical averages. Neither scheme replaces king safety, promotion threats or piece activity.""",
    """Keep a running material ledger: write what White gains, what White gives up and the net result. Repeat with a hypothetical black king on b8 instead of g8. The move Qxa7 would then allow Kxa7, giving a queen for a rook, so the arithmetic and the best choice change. This single-square comparison is more useful than memorizing that rooks always outrank bishops.""",
    ('Qxa7', 'Bg5', 'Qd4'),
    ('Check defenders before applying piece values.', 'The queen captures a genuinely undefended rook; the king on g8 cannot recapture.', 'The bishop retreats to a new diagonal; this is illustrative, not forced.', 'The queen returns towards the centre after banking the material gain.'),
    (('What must you check before taking a supposedly free rook?', 'Whether the capturing piece can be recaptured or a stronger threat exists.', 'Only that a rook is worth five.', 'The value gained means little if the move loses a queen or allows mate.', 'A five-unit victim does not justify every capture.'),
     ('Using the usual beginner values, what is rook for knight worth?', 'An approximate gain of two units.', 'An approximate loss of two units.', 'Five minus three is about two; the position can modify that judgment.', 'The rook is normally the more valuable piece.')),
    ('A defended rook is not free just because the queen can reach it.', 'Approximate values guide evaluation; they do not prove a tactical sequence is safe.'))

GUIDES['values-depend-on-position'] = _guide('values-depend-on-position', (62, 69),
    ('Promotion can outweigh a small material capture.', 'The urgency of promotion depends on concrete threats.', 'A bishop or knight’s usefulness depends on its available work.'),
    """The e7-pawn is one step from becoming a queen. Promoting with check creates a much larger material change than capturing a knight, and the check makes Black answer king danger first. In the line, e8=Q+ forces a response to check, although Kg7 is only one of several legal king moves. White then takes the knight as well. Notice an important limitation: Bxa5 first is also winning on this particular board, because Black cannot stop e8 on the next move. It is incorrect to say that capturing the knight would throw away a queen. The quiz explicitly asks you to promote now; that is a task requirement, not an engine claim that every alternative loses. To demonstrate urgency you would need an actual threat to the promotion square or pawn.""",
    """Compare two candidate lines before deciding that a pawn is worth more than a piece. Ask what happens after promotion and after the capture, including the opponent's best reply. Then add a black rook controlling e8 and reconsider: promotion may now fail. In a separate game, compare a bishop trapped behind its own fixed pawns with a knight on a supported central square. Describe their jobs before quoting their point values.""",
    ('e8=Q+', 'Kg7', 'Bxa5'),
    ('The pawn can promote safely, while the bishop also has a loose knight available.', 'Promotion creates a queen and checks along rank eight.', 'Black escapes the check; Kg7 is an example, not the only legal reply.', 'White also captures the knight. Promotion did not require abandoning that later gain.'),
    (('Does Bxa5 first lose the promotion in this exact diagram?', 'No; it is also winning, but the exercise requests promotion now.', 'Yes; the pawn disappears if it does not promote immediately.', 'There is no black move that stops the safe e8 promotion here.', 'The position contains no such urgency; do not invent a threat.'),
     ('When can an advanced pawn be worth less than it appears?', 'When the promotion square is controlled and the new piece can be captured.', 'Never: a seventh-rank pawn is always worth a queen.', 'The value depends on whether promotion can actually be completed safely.', 'Being close to promotion is not the same as possessing a safe queen.')),
    ('Do not describe a requested move as uniquely winning when other moves also win.', 'A pawn’s potential value depends on its route, enemy control and available time.'))

GUIDES['piece-characteristics'] = _guide('piece-characteristics', (66, 70),
    ('Piece activity depends on usable lines and squares.', 'An open file is useful when it serves an entry or target.', 'The king’s appropriate role changes as danger decreases.'),
    """The rook example deliberately isolates a line piece. With no pawns on the e-file, Re1 places the rook on an unobstructed vertical road. Black's king can still move, and nothing is won merely by choosing a central file on an almost empty board. The next rook move, Re7+, demonstrates an entry into the enemy's area and a check. Compare this with a fuller position: an open file is valuable when the rook can penetrate, attack a weak pawn or restrict a king. A bishop needs diagonals, while a knight can jump over a locked pawn chain. Bishops never change square colour; knights do. The queen combines lines but remains vulnerable to attacks from cheaper pieces. Pawns create space and permanent weaknesses because they cannot retreat.""",
    """After each rook move, trace its rank and file and identify what has changed. Then imagine an own pawn on e2: Re1 would no longer have the same scope. Repeat the exercise with a bishop behind its own pawns and with a knight behind them; the obstruction affects them differently. Finally explain why walking the king towards the centre is sensible in a quiet ending but dangerous in an opening full of queens and open lines.""",
    ('Re1', 'Kg7', 'Re7+', 'Kg6'),
    ('The rook needs a usable line; the e-file is clear.', 'The rook occupies that clear file.', 'Black approaches without moving into the rook’s line; this reply is illustrative.', 'The rook uses the file to reach the seventh rank with check.', 'The king leaves the checked rank; the rook has gained an active post.'),
    (('Why might an open file still be unimportant?', 'It may offer no useful entry square or target.', 'Any open file wins material automatically.', 'Activity needs a purpose, such as penetration or pressure on a weakness.', 'A clear road alone does not provide a victim or mating net.'),
     ('Which piece can jump over a locked pawn chain?', 'A knight.', 'A bishop.', 'Knights jump; their intermediate squares do not obstruct them.', 'A bishop cannot pass through any occupied square.')),
    ('An open file is a means to activity, not an automatic material gain.', 'Do not centralize an exposed king simply because kings become strong in quiet endings.'))

GUIDES['obstruction'] = _guide('obstruction', (69, 72),
    ('Your own pieces can obstruct useful lines.', 'Either e3 or e4 opens the f1-bishop’s diagonal.', 'An obstruction can be beneficial when it restricts the opponent.'),
    """At the starting position the bishop on f1 cannot move: e2 and g2 are occupied by its own pawns. Moving the e-pawn vacates one of those blocking squares. Both e3 and e4 accomplish that particular task, so both are accepted. They create different central structures, which matters for a broader opening choice. The worked line uses e4 because it also claims central space. After Black's e5, Bc4 follows the newly opened diagonal through e2 and d3 to c4. The original e2-pawn no longer stands in the way. Black's Nf6 then develops and attacks e4, demonstrating that opening a line is only one part of the position. You still have to respond to new threats. Obstruction is not always bad: your pawn can also deny an enemy rook a file or imprison an enemy bishop.""",
    """Before moving a blocked bishop, name the first occupied square on each diagonal. Do not draw an arrow through it and pretend that the bishop already attacks beyond it. After e4, trace every now-accessible square and distinguish control from a legal move when another piece occupies the destination. Then restore the e-pawn and try e3. Explain precisely what both moves share and what central difference remains.""",
    ('e4', 'e5', 'Bc4', 'Nf6'),
    ('The pawn on e2 obstructs the bishop’s c4 diagonal.', 'Vacating e2 opens that diagonal and occupies a central square.', 'Black answers in the centre; e5 is a normal choice, not forced.', 'The bishop can now travel through the cleared diagonal.', 'Black develops and attacks e4, so the next decision needs another threat check.'),
    (('Does e3 also free the bishop on f1?', 'Yes; e2 becomes empty.', 'No; only a two-square pawn move can open a bishop.', 'The relevant change is vacating e2, not the distance travelled.', 'The bishop’s line opens after either legal e-pawn advance.'),
     ('Can an obstruction help your position?', 'Yes, if it blocks an enemy line or restricts an enemy piece.', 'No; every obstruction should be removed.', 'A blocker can be a useful defensive or restrictive resource.', 'Removing a blocker may activate an opponent’s rook or bishop.')),
    ('A piece does not attack through the first occupied square on its line.', 'Do not assume every pawn move frees the piece you wanted to activate.'))

GUIDES['cutting-off'] = _guide('cutting-off', (72, 73),
    ('Control of a rank can restrict a king without check.', 'A fence must remain safe and unobstructed.', 'Restriction gives your other pieces time to improve.'),
    """Rh5 places the rook on a clear fifth rank. Black's king starts above that rank and cannot cross any attacked square on it. The rook does not check from h5, and it does not stop the king from moving within its remaining area. Kb7 and Kc6 in the worked line show that freedom. White uses the time to bring the king closer with Kg3. This is a useful distinction: attacking a king directly is not the only way to reduce its choices. A fence also has conditions. If an enemy piece could capture the rook, or if a pawn blocked the fifth rank, the full claimed barrier might disappear. And the rook must not abandon that barrier just to give an irrelevant check. Restriction becomes useful when it supports a follow-up plan.""",
    """Mark every square of rank five after Rh5 and list the black king's legal moves. Notice that the moves above the fence remain available. Then move the white king towards the restricted king while keeping the rook safe. As a transfer exercise, put a black pawn on d5 and trace the rook's line again: it reaches that pawn but does not control squares beyond it until the obstruction is removed.""",
    ('Rh5', 'Kb7', 'Kg3', 'Kc6'),
    ('Black’s king is above the proposed fifth-rank fence.', 'The rook controls the clear fifth rank without giving check.', 'Black stays above the fence; it still has legal choices.', 'White improves the king while maintaining the barrier.', 'Black can approach the barrier but cannot step onto the attacked fifth rank.'),
    (('Does cutting a king off require check?', 'No; control of crossing squares can be enough.', 'Yes; a non-check move cannot restrict a king.', 'A king may not move into attacked squares even when it is not currently checked.', 'Control restricts future moves as well as current checks.'),
     ('What could invalidate a claimed full-rank rook fence?', 'A blocker on that rank or a way to capture the rook.', 'The enemy king having any legal move at all.', 'The line must really be clear and its attacking rook safe.', 'The king can move within its remaining area without crossing the fence.')),
    ('A restricted king is not necessarily in check or immobile.', 'Do not claim control beyond a blocker on the rook’s line.'))

GUIDES['edge-restriction'] = _guide('edge-restriction', (73, 74),
    ('A knight generally has more possible jumps near the centre.', 'Legal mobility also depends on occupied squares.', 'Different pieces are affected differently by the board edge.'),
    """From the starting position the queen's knight can move to c3 or a3, but not to d2: its own pawn occupies d2. A knight jumps over intermediate pieces, yet it cannot land on a square occupied by a friendly piece. Nc3 directs it towards d5 and e4. On an otherwise empty board a knight on c3 has eight destinations, while one on a3 has four; count them rather than relying on the phrase 'knight on the rim'. Actual legal moves may be fewer because of friendly pieces or king danger. Not every piece loses the same mobility at the edge. An unobstructed rook attacks fourteen squares from any square. A corner bishop attacks seven squares, while a central bishop can attack thirteen. The geometry supplies a reason for centralization, but tactics can still justify an unusual edge square.""",
    """Draw the knight's possible destinations from c3 and a3 on an empty board, then repeat with the starting pieces restored. Separate geometric destinations, attacks and legal moves. Next give the edge knight a specific tactical target and ask whether reaching it might justify the smaller mobility. In your games use central development as a sensible starting preference, then check concrete threats and whether the chosen square can be maintained.""",
    ('Nc3', 'e5', 'Nf3', 'Nc6'),
    ('White can develop the b1-knight towards c3 or a3.', 'Nc3 develops towards the central squares d5 and e4.', 'Black occupies the centre; this is a normal illustrative reply.', 'White develops the other knight as well.', 'Black also chooses a central knight post, showing the same geometric preference.'),
    (('Why is Nd2 unavailable from b1 in the starting position?', 'A white pawn occupies d2.', 'A knight cannot jump over pieces.', 'Knights can jump, but cannot land on their own men.', 'Intermediate blockers do not stop a knight’s jump.'),
     ('How many squares does an unobstructed rook attack from a corner?', 'Fourteen.', 'Seven.', 'It has seven squares on its rank and seven on its file.', 'Seven counts only one of the rook’s two directions.')),
    ('A knight jumps over pieces but cannot land on a friendly piece.', 'Do not apply a knight’s edge mobility rule unchanged to rooks or bishops.'))

GUIDES['defensive-piece'] = _guide('defensive-piece', (74, 77),
    ('A defensive duty can limit a piece’s freedom.', 'Removing the danger can release the defender.', 'Identify the defended target before naming a defender tactic.'),
    """The rook on a4 attacks the white rook on e4. The bishop on f3 protects e4, so it has a defensive duty: after an ordinary retreat off that diagonal, Black could capture the rook without losing its own rook in return. Re3 removes the white rook from rank four. That means the bishop no longer has to stay on its old diagonal just to support e4. In the line Black's Ra2 is an illustrative active move, and White then brings the bishop to d5. Do not call the bishop absolutely immobile: it could move if a stronger tactical reason justified abandoning the rook, or to another square that still defended e4. For example Bg2 stays on the same defending diagonal. The important relationship is the job, not merely the bishop's original square.""",
    """Cover the bishop with your finger and ask what Black would capture if it disappeared. Then compare Be2, which leaves the duty, with Bg2, which continues to defend e4 from the same diagonal. Finally move the rook to e3 and repeat the question. The disappearance of the original danger explains the bishop's new freedom. Try the same reasoning with a queen responsible for two rooks; that leads to the separate overloaded-defender lesson.""",
    ('Re3', 'Ra2', 'Bd5'),
    ('The bishop guards e4 because the opposing rook attacks along rank four.', 'The rook leaves the attacked rank, releasing that duty.', 'Black activates the rook on another rank; this is not forced.', 'The bishop can choose an active diagonal without abandoning an attacked rook on e4.'),
    (('What makes f3’s bishop a defender in the initial diagram?', 'It protects the attacked rook on e4.', 'Every bishop is automatically tied to defence.', 'The duty is a concrete relationship between attacker, target and defender.', 'The title does not follow from the piece’s type.'),
     ('Would Bg2 abandon the e4-rook?', 'No; g2–f3–e4 is still a defending diagonal.', 'Yes; any bishop move abandons it.', 'Trace the new diagonal before deciding the duty was abandoned.', 'Some moves change the square without changing the defensive job.')),
    ('An attacked piece and a piece tied to defending something else are different ideas.', 'A defender may have several squares from which it can keep doing its job.'))

GUIDES['pin'] = _guide('pin', (77, 80),
    ('An absolute pin forbids exposing your own king to check.', 'Breaking a pin must also preserve material safety.', 'A pinned line piece may sometimes move along the pin line.'),
    """Trace a5–b4–c3–d2–e1. The bishop's line ends at the white king, with the knight on c3 as the blocker. A knight jump would uncover check and is illegal. Ke2 moves the king off that line. The b2-pawn continues to protect c3, so Bxc3 could be answered by bxc3. This extra defender matters: simply unpinning a piece does not make it safe from capture. Kd2 is a useful trap for your reasoning because d2 is still on the very same diagonal; that king move would not unpin the knight. The worked line gives Black an ordinary king move, after which the knight jumps to d5 to demonstrate its restored legal freedom. Black was not compelled to wait; it could instead exchange on c3.""",
    """First identify attacker, blocker and protected king in that order. After each candidate king move, redraw the entire diagonal rather than guessing from the changed king square. Then ask whether the knight is still defended. As a transfer exercise, replace the knight with a rook pinned along a file: it may be able to move up or down that file without exposing check. Absolute pins prohibit exposure of the king, not movement in every conceivable direction.""",
    ('Ke2', 'Kg7', 'Nd5'),
    ('The a5-bishop pins the c3-knight to the king on e1; b2 separately protects the knight.', 'The king leaves the diagonal, so knight moves no longer uncover check.', 'Black makes an illustrative king move; exchanging on c3 was also possible.', 'The knight can legally jump now that the king is off the line.'),
    (('Would Kd2 break this diagonal pin?', 'No; d2 lies on a5–b4–c3–d2.', 'Yes; every king move unpins a piece.', 'The line must be traced after the move; d2 remains behind c3.', 'Moving the king along the same line may preserve the pin.'),
     ('Can an absolutely pinned rook ever move?', 'Yes, if its move keeps the king shielded from check.', 'No; an absolute pin forbids every move.', 'Movement along the pin line or capture of the pinning piece can sometimes be legal.', 'The rule forbids leaving the king in check, rather than all piece movement.')),
    ('Unpinning does not by itself defend a loose piece against capture.', 'Do not mistake a move along the pin line for a move off that line.'))

GUIDES['time'] = _guide('time', (81, 81),
    ('Compare threats by counting alternate moves.', 'A promotion threat must have an empty or legally capturable destination.', 'Forcing replies can deny time to an opposing plan.'),
    """The pawn on f2 really can advance to f1: that square is empty. White's rook stands on b2, so it can capture the pawn horizontally with Rxf2 before Black moves. After a king move such as Kh2, Black can promote, and a rook on b2 cannot jump diagonally to f1 to capture the new queen. Contrast a rook already sitting on f1: that rook would obstruct a straight pawn advance, so claiming f1=Q would be illegal. This is why an accurate board matters more than dramatic wording about urgency. After Rxf2 the worked line continues with ordinary king development; the original emergency has gone. In more complex positions a check may postpone the pawn's move because Black must answer the king attack, but every checking sequence must be calculated until the pawn is genuinely stopped.""",
    """Write two branches, Rxf2 and Kh2, alternating the sides carefully. In the slow branch actually place a queen on f1 and trace every possible rook capture; do not assume that a nearby rook can take it. Then change the rook's starting square to f1 and explain why the threat changes completely. This tests whether you understand tempo as a sequence of legal moves rather than merely a race between imagined ideas.""",
    ('Rxf2', 'Kb7', 'Kg2'),
    ('Black threatens a legal f1 promotion, and White has one turn to act.', 'The rook removes the pawn before it can promote.', 'Black brings the king closer; there is no longer a promotion threat.', 'White can now spend time on improving the king because the urgent danger is gone.'),
    (('Why would a rook on f1 change this example?', 'It would block the pawn’s straight advance onto f1.', 'It would make the pawn promote with a capture straight ahead.', 'A pawn cannot advance into an occupied square.', 'Pawns capture diagonally, not straight forward.'),
     ('Why are checks useful when racing a pawn?', 'They may force the opponent to spend the reply on king safety.', 'Every check permanently prevents promotion.', 'A check can buy time only for as long as the calculated sequence maintains the relevant restriction.', 'Once checks end, the pawn may still promote.')),
    ('Check the legality of the opponent’s claimed threat before reacting to it.', 'A temporary check is not the same as permanently stopping a pawn.'))

GUIDES['forcing-moves'] = _guide('forcing-moves', (82, 99),
    ('A forcing move limits the opponent’s useful replies.', 'Checks must be answered, while captures and threats require evaluation.', 'Calculate forcing candidates before selecting a plan.'),
    """The queen on h2 can check from several squares. Qh5+ attacks e8 along h5–g6–f7–e8 and makes Black answer check. The exercise accepts any legal checking move because its stated objective is to give check, not to find a uniquely best queen move. In the worked line Black chooses Ke7, after which White can improve the distant king. That king reply is not forced: other escapes exist. This distinction matters when describing forcing play. 'Forcing' does not necessarily mean only one legal response; it means the response is constrained by a danger. A harmless check may constrain the reply without improving your position. Captures and threats can also be forcing when ignoring them would lose important material or permit mate. They do not enjoy check's automatic rule-based priority.""",
    """List all legal checks and inspect each destination for capture. For every surviving candidate, count the opponent's replies and state what useful result follows. Then list captures and direct threats. Do not stop at the first check you see. In this very sparse position many moves still win eventually; the exercise isolates the definition of a check as a forcing move rather than claiming a single precise route to victory.""",
    ('Qh5+', 'Ke7', 'Kb2'),
    ('White has several checks; examine the queen’s lines.', 'The diagonal check makes king safety Black’s immediate obligation.', 'Black chooses one legal escape; the position does not force this exact king square.', 'White approaches with the king, showing a useful follow-up rather than checking from habit.'),
    (('Must a forcing move leave exactly one legal reply?', 'No; it may leave several constrained replies.', 'Yes; otherwise it is not forcing.', 'A check can allow several king moves while still requiring a response to check.', 'Uniqueness is stronger than the meaning of forcing.'),
     ('Which question should follow “I can give check”?', 'What does the check achieve after the best reply?', 'How can I check again regardless of the position?', 'The value lies in the resulting position and continuation.', 'Unnecessary checks can help the defender or waste time.')),
    ('Forcing does not mean automatically good.', 'Do not call a particular reply forced until the alternatives have been ruled out.'))

GUIDES['check-as-forcing'] = _guide('check-as-forcing', (82, 85),
    ('Every check requires a legal answer.', 'Capturing the checker is itself an answer to check.', 'A safe check still needs a useful purpose.'),
    """Qe5+ checks up the e-file from a safe distance. The black king cannot capture a queen three ranks away, so it must choose a legal escape. By contrast, Qd8+ offers an undefended queen beside the king and permits Kxd8. That move is still a forcing check in the rules sense: Black must answer it, and capturing the queen is one such answer. What makes it poor is the resulting material loss, not a failure to be check. The quiz specifies the safe check on e5 so that other legal safe checks are not labelled chess mistakes; they simply lie outside this particular square exercise. In the line Black plays Kf7 and White brings the king closer. The check is an example of constrained response, not a claim that it is the fastest possible mate.""",
    """For Qe5+ enumerate the escape squares and explain why the king cannot capture the checker. For Qd8+ physically play Kxd8 and inspect the resulting bare kings: the queen sacrifice has drawn a winning position. Next compare a deliberate checking sacrifice whose capture enables mate. The checking piece's survival is not the general test; the entire continuation is. Always distinguish a rule-forced response from a strategically useful result.""",
    ('Qe5+', 'Kf7', 'Kb2'),
    ('The queen can check safely from a distance or recklessly from beside the king.', 'The e-file check cannot be met by a king capture of the distant queen.', 'Black chooses a legal escape; other safe king replies also exist.', 'White improves the king rather than assuming that another check must be best.'),
    (('Is Qd8+ still a check even though Kxd8 is legal?', 'Yes; capturing the checker answers that check.', 'No; a capturable piece cannot give check.', 'A checking piece can be captured if the capture leaves the king safe.', 'Capture of a checking piece is a standard defence.'),
     ('Can a checking sacrifice ever be correct?', 'Yes, if the calculated continuation justifies the material given.', 'No; every checker must survive.', 'Mate or another adequate benefit can justify a sacrificed checker.', 'Survival is not an absolute requirement; the final result matters.')),
    ('A capturable checker still gives check.', 'A safe check may still waste time if it helps the opponent’s king.'))

GUIDES['dual-attack'] = _guide('dual-attack', (85, 92),
    ('A fork attacks two targets with one piece.', 'A checking fork makes king safety take priority.', 'Winning a queen is not always the same as winning the game.'),
    """The knight on b5 can move to c7, attacking a8 and e8 simultaneously. The king on a8 is checked, while the queen on e8 is attacked. Neither target can capture the knight: the queen's line to c7 is not a queen move, and the king is too far away. Black must answer check, for example with Kb7, and White can then play Nxe8. Inspect the final position carefully. White has king and knight against a lone king, so the game is drawn for insufficient mating material. The fork wins the queen and rescues a bad position, but does not create a forced win. This is an important habit: evaluate the result after the tactic. A material label such as 'queen won' is not a substitute for checking what remains on the board.""",
    """Trace every knight destination from c7 and identify which two squares contain targets. Then test every possible capture of the forking knight before accepting the combination. Finally remove the captured queen and name the ending. As a transfer exercise, add a safe extra white pawn and ask how the resulting task changes: White may now have winning chances, but must still convert the pawn rather than merely admire the fork.""",
    ('Nc7+', 'Kb7', 'Nxe8'),
    ('White is badly behind in material but can fork the aligned king and queen.', 'The knight checks a8 and attacks e8 at the same time.', 'The king answers check; Kb7 is one example of a legal response.', 'White captures the queen. The resulting king-and-knight versus king position is an immediate insufficient-material draw.'),
    (('What is the result after this fork captures the queen?', 'A draw: only king and knight remain against king.', 'A forced win because the queen was captured.', 'A lone knight cannot mate a lone king with its king’s help.', 'Winning a queen can rescue a draw rather than win the whole game.'),
     ('What can refute an apparent fork?', 'A move that captures the attacker or answers both threats.', 'Nothing: two targets always means a piece is lost.', 'Targets can sometimes capture, check, interpose or defend each other.', 'The two-threat label must be supported by calculation.')),
    ('Count the remaining material after the tactic, including whether mate is possible.', 'Do not assume every fork wins: test captures and combined defences.'))

GUIDES['capture-as-forcing'] = _guide('capture-as-forcing', (92, 96),
    ('A capture changes material immediately.', 'A recapture may be sensible without being legally compulsory.', 'Exchange and sacrifice describe different material transactions.'),
    """The rook on e1 has a clear route to the queen on e6. Rxe6 removes the queen, and Black has no recapture because the king on a8 is far away. This simple capture demonstrates immediate material gain. It does not demonstrate a forced recapture; there is none. In a fuller position a capture of a defended piece often constrains the opponent because failing to recapture loses material. Even then a countercheck, mating threat or stronger capture may take priority. An equal-value transaction is an exchange. Deliberately giving more than you immediately receive is a sacrifice, justified only by a resulting benefit. The source explores exchanges for structure, open lines, elimination of dangerous pieces and tempo. Those purposes matter beyond the easy loose-queen exercise here, so the separate purposeful-exchanges lesson develops them.""",
    """Before Rxe6, name every defender of e6 and inspect whether moving the rook exposes the white king. After the capture, reset the material count and say why a normal king move is now sufficient for Black rather than inventing a recapture. Then imagine a black rook on e8 defending the queen: calculate Rxe6 Rxe6 and determine whether giving a rook for a queen would still be profitable.""",
    ('Rxe6', 'Kb7', 'Kf2'),
    ('The queen is genuinely undefended on an open rook file.', 'White captures the queen and the rook survives.', 'Black cannot recapture, so it makes a king move instead.', 'White improves the king in the resulting rook-versus-king winning ending.'),
    (('Is a recapture always compulsory after a capture?', 'No; check the opponent’s threats and alternatives.', 'Yes; chess rules require it.', 'Only king safety imposes a legal obligation; material recaptures are evaluated choices.', 'The rules do not force a player to recover material.'),
     ('What is a sacrifice?', 'Deliberately giving more material than you immediately receive for another benefit.', 'Any capture of an undefended piece.', 'The material cost distinguishes a sacrifice from an ordinary gain or equal exchange.', 'Taking a loose queen is a gain, not a sacrifice.')),
    ('Do not invent a forced recapture where no defending piece exists.', 'After a capture, examine the opponent’s forcing alternatives before continuing your plan.'))

GUIDES['promotion-as-forcing'] = _guide('promotion-as-forcing', (96, 98),
    ('A safe promotion can change the material balance sharply.', 'Promotion with check constrains the immediate reply.', 'The promoted piece must be chosen for the resulting position.'),
    """The pawn on b7 has an empty b8 destination. A queen appearing there checks the king on g8 along the eighth rank. Black cannot spend that reply moving the knight on h2 unless the move also answers check, and in this case the knight has no such defence. The king moves, for example to f7, after which Qxh2 captures the knight along b8–c7–d6–e5–f4–g3–h2. That long diagonal is worth tracing on the board. Several king escapes exist, so do not confuse 'must answer check' with 'has exactly one reply'. A knight promotion on b8 would not check g8 and leaves vastly less material. However, other positions may require a knight check or a rook promotion to avoid stalemate; those exceptions receive their own underpromotion exercise.""",
    """Inspect b8 for enemy control before moving the pawn. After promotion, list Black's legal check responses and identify the new queen's capture route to h2. Repeat with b8=N and explain both changes: no check on g8 and much less force. Then study the separate underpromotion position and compare why the extra queen-controlled squares are harmful there. The correct promotion depends on the actual legal replies, not on a permanent rule to choose queen or knight.""",
    ('b8=Q+', 'Kf7', 'Qxh2'),
    ('The pawn can promote safely while the distant knight is a later target.', 'A queen appears on b8 and checks along rank eight.', 'Black answers check with one of several king moves.', 'The queen follows the long diagonal and captures the knight that could not be saved during the check response.'),
    (('Does promotion with check always leave only one legal reply?', 'No; the king may have several escapes.', 'Yes; “forcing” means a unique move.', 'The obligation is to answer check, which can sometimes be done in several ways.', 'A constrained reply is not necessarily a unique reply.'),
     ('Why might a rook promotion be better than a queen promotion?', 'The queen could cause stalemate while the rook preserves a win.', 'A rook is normally worth more than a queen.', 'Avoiding a drawn terminal position can matter more than maximum nominal value.', 'The exception comes from geometry, not the rook’s material value.')),
    ('Do not overlook a defender controlling the promotion square.', 'Use underpromotion for a concrete reason, such as check or avoiding stalemate.'))

GUIDES['threats'] = _guide('threats', (98, 99),
    ('A threat is a concrete damaging continuation.', 'Both Qh5 and Qf3 threaten Qxf7 mate here.', 'A mate threat can be defended and is not a forced win.'),
    """The bishop on c4 protects f7. A queen on h5 attacks f7 diagonally; a queen on f3 attacks it vertically. After an irrelevant black move such as a6, either placement permits Qxf7 mate. Therefore both queen moves answer the exercise. This is a useful warning against memorizing a single square as the definition of a tactic. Black has real defences: g6 blocks the h5–f7 diagonal while attacking the queen, and after Qf3, Nf6 can interpose on the f-file. In the worked line White answers g6 with Qf3, then Black plays Nf6. The mate threat has been met, and White has moved the queen twice while Black gains useful moves. Recognizing a threat is valuable, but repeatedly making easily defended threats can be a poor overall plan.""",
    """Play the ignored-threat branch Qf3 a6 Qxf7 mate and explain every king escape that fails. Then reset and examine Qh5 g6: identify the newly blocked diagonal and the attack on the queen. Compare the two lines before claiming a forced attack. In your own games write the threat in the form 'If the opponent ignores this, I can…', then immediately search for the opponent's strongest defence rather than stopping at the attractive possibility.""",
    ('Qh5', 'g6', 'Qf3', 'Nf6'),
    ('The bishop protects f7; a queen can join the attack from two different directions.', 'Qh5 threatens Qxf7 mate, but Black has defences.', 'The pawn blocks the diagonal and attacks the queen, meeting the immediate threat.', 'The queen retreats to another attacking line; this also threatens f7.', 'The knight blocks that line while developing. The earlier mate threat was not a forced win.'),
    (('Does Qf3 create the same Qxf7 mate threat as Qh5 here?', 'Yes; it attacks f7 up the clear f-file.', 'No; only Qh5 can threaten that mate.', 'The bishop supplies protection and either queen line reaches f7.', 'The tactical relationship matters more than one memorized queen square.'),
     ('What does g6 achieve against Qh5?', 'It blocks the diagonal to f7 and attacks the queen.', 'It ignores the mating threat.', 'One move can both defend a target and create a threat of its own.', 'The new pawn on g6 lies directly on h5–f7.')),
    ('A mate threat is not the same as a forced mate.', 'A different move can realize the same tactical idea and should receive correct credit.'))

GUIDES['coordination'] = _guide('coordination', (100, 104),
    ('Coordinated pieces contribute different parts of one plan.', 'Protection can make a queen capture safe from the king.', 'Count values and capture order as well as attackers.'),
    """The bishop and queen do different work in the f7 pattern. The queen supplies the check from f7; the bishop makes Kxf7 illegal by protecting that square. Without the bishop, the king could capture an undefended queen after Qxf7. Simply saying 'two attackers beat one defender' hides this crucial king-safety rule and can lead to bad exchanges elsewhere. For example two queens attacking a pawn do not justify giving one queen to a defending pawn. In the worked line Black meets the first threat with g6 and the second with Nf6, so White's pieces must find another coordinated plan. The book's extended bishop-and-knight ending is another form of coordination: king, bishop and knight control different escape squares. The dedicated corner-pattern lesson introduces that demanding technique without pretending one exercise supplies full mastery.""",
    """Remove the bishop from c4 and test Qxf7 again. Then restore it and identify why the king's capture is now illegal. This isolates the precise contribution of the second piece. Next compare the rook, bishop and knight in a corner mating net: list the squares each covers and look for overlaps or gaps. Coordination is often about complementary jobs, not merely placing several attackers near the same victim.""",
    ('Qh5', 'g6', 'Qf3', 'Nf6'),
    ('The bishop supplies f7 protection; the queen can supply a mating check.', 'The queen joins the bishop’s target, creating a concrete threat.', 'Black interrupts the queen’s route rather than allowing the attack.', 'White tries another queen route to the protected target.', 'Black develops while screening f7, reminding White that coordination must work against resistance.'),
    (('Why can the king not capture a queen on f7 when the bishop is on c4?', 'The bishop protects f7, so Kxf7 would move into check.', 'A king can never capture a queen.', 'Kings can capture undefended queens but cannot enter an attacked square.', 'A queen’s name gives no immunity from a legal king capture.'),
     ('Is a favourable attacker count alone enough to justify a capture?', 'No; consider values, order, pins and forcing replies.', 'Yes; two attackers always beat one defender.', 'Some attackers are expensive or unable to move, and counterchecks can interrupt the sequence.', 'Raw numbers cannot replace the actual exchange calculation.')),
    ('Identify each piece’s specific job instead of merely counting nearby pieces.', 'A coordinated threat still needs recalculation after a defensive reply.'))

GUIDES['unprotected-king'] = _guide('unprotected-king', (104, 104),
    ('King safety depends on cover, lines and attacking forces.', 'Castling can improve safety and rook activity.', 'An exposed king can justify a calculated sacrifice.'),
    """This exercise uses the defensive side of the idea: White can castle before central lines open. The king moves to g1 behind f2, g2 and h2, while the rook moves to f1. Castling is legal because White is not in check, f1 and g1 are empty and the king crosses no attacked square. Black's Nf6 in the line develops and attacks e4; White supports that pawn with d3, and Black supports e5 with d6. The resulting position still needs careful play: castling does not make a king invulnerable. The source's attacking example concerns a king whose last defenders are removed by sacrifices and forcing checks. The transferable lesson is to count available attacking pieces and open lines against the remaining cover. A sacrifice must be calculated; an exposed king alone does not guarantee mate.""",
    """Before castling, verify every legal condition and trace the enemy bishop's diagonal. After castling, name the pawn shield and inspect which pawn move would create a new weakness. For attacking practice, remove one shielding pawn and ask which rook file or bishop diagonal becomes relevant. Do not conclude that every uncastled king is immediately lost: a closed centre may provide time, while an open file with several attackers may demand an urgent response.""",
    ('O-O', 'Nf6', 'd3', 'd6'),
    ('White’s developed minor pieces have cleared legal kingside castling.', 'The king leaves the centre and the rook becomes more active.', 'Black develops and attacks e4, so king safety does not end White’s other responsibilities.', 'White supports the centre and opens the c1-bishop.', 'Black similarly supports the central pawn; both sides must keep balancing safety and activity.'),
    (('Does castling guarantee that the king cannot be attacked?', 'No; pawn weaknesses and open lines can still expose it.', 'Yes; a castled king is always safe.', 'The pawn shield and piece placement still have to be evaluated.', 'Castling improves typical safety but provides no permanent immunity.'),
     ('What must justify a sacrifice against an exposed king?', 'A calculated continuation with adequate benefit.', 'The fact that the opponent has not castled.', 'Check the defender’s replies and the final result, not just the appearance of danger.', 'An uncastled king may still have enough cover or defenders.')),
    ('Do not treat every uncastled king as already lost.', 'Before sacrificing, calculate the defender’s strongest checks, captures and escape routes.'))

GUIDES['centralization'] = _guide('centralization', (105, 105),
    ('Central influence can improve mobility and access to both wings.', 'Nf3 controls central squares without occupying one of the central four.', 'A central square must be safe or supported.'),
    """Nf3 attacks d4 and e5, two of the four central squares. The knight does not need to land on e4 or d4 to contribute to central control. Nh3 has fewer geometric destinations and misses those key squares, which explains the usual development preference. In the line Black stakes space with d5, White answers d4 and Black develops Nf6. This is not a forced opening sequence; both sides are showing central aims. Later a supported knight on d5 or e5 can influence both wings, but an unsupported knight may be chased by a pawn. Endgame king centralization follows the same distance principle when immediate mating danger is low. In a position with queens and open files, marching the king centrally can instead invite checks. Activity must be balanced with safety.""",
    """After Nf3, mark the central squares it attacks and distinguish controlling a square from occupying it. Compare the knight's routes to the kingside and queenside from f3 and h3. Then imagine Black can play a pawn move attacking your intended outpost: decide whether support, a tactical reply or another destination is needed. In an ending, count the king's walking distance to targets on both wings before choosing a direct pawn chase.""",
    ('Nf3', 'd5', 'd4', 'Nf6'),
    ('White can develop the kingside knight towards central influence.', 'The knight controls d4 and e5 and clears g1.', 'Black claims central space rather than reacting passively.', 'White occupies another central square and opens lines for development.', 'Black also develops towards the centre; each player continues pursuing useful central influence.'),
    (('Must a piece occupy d4, e4, d5 or e5 to help control the centre?', 'No; it can attack those squares from elsewhere.', 'Yes; only occupation counts.', 'A knight on f3 directly attacks d4 and e5.', 'Control can restrict the opponent before you occupy a square.'),
     ('When is centralizing a king most attractive?', 'In a quiet ending where checks and mating danger are limited.', 'Whenever the centre is open, regardless of enemy queens.', 'The king’s fighting activity grows when immediate king danger has subsided.', 'Open lines and major pieces may make central exposure dangerous.')),
    ('Centralization does not excuse placing a piece on an attacked square without compensation.', 'The king’s best role depends on the stage and danger level, not a universal centre rule.'))

GUIDES['seventh-rank'] = _guide('seventh-rank', (105, 107),
    ('An invasion is useful when it reaches targets or restricts a king.', 'Seventh-rank pawns can be attacked from the side.', 'A rook does not control squares beyond the first blocker.'),
    """The a-file is open, so Ra7 reaches the seventh rank in one move. The pawn on b7 is now attacked sideways and can be captured with Rxb7 if Black spends the reply elsewhere. The worked line uses Kg8 as that illustrative reply. Notice what the rook does not yet do: from a7 its line stops at b7. It cannot simultaneously claim control of g7 or h7 through that pawn. This is why an invasion diagram with real targets is more informative than an empty-board slogan about owning a whole rank. After Rxb7 the rook's horizontal scope increases, but the h7-pawn is protected by the nearby king on g8 and must not be described as automatically free. In fuller positions the defender may contest the open file, exchange rooks or cover the entry square.""",
    """Trace the rook's line after Ra7, after Rxb7 and after Black's pawn move h6. For each position identify the first blocker and all genuine targets. Then ask how Black could have defended b7 or stopped the invasion earlier. The source develops a whole open-file campaign, not merely a rook jump. In your games plan the entry square, the opposing challenge and the next target together instead of invading without a follow-up.""",
    ('Ra7', 'Kg8', 'Rxb7', 'h6'),
    ('White has a clear entry file and a pawn target on the seventh rank.', 'The rook reaches a7 and attacks b7 from the side.', 'Black chooses a king move and leaves b7 undefended; this is illustrative, not forced.', 'White captures b7 and extends the rook’s view along the rank.', 'Black advances another pawn. Its new square and king protection must be checked before any further capture.'),
    (('Does a rook on a7 see through a black pawn on b7?', 'No; its line stops at that pawn.', 'Yes; seventh-rank rooks control the whole rank automatically.', 'Sliding pieces cannot attack through occupied squares.', 'An invasion does not cancel the normal blocking rule.'),
     ('Why is the seventh rank often a useful invasion target?', 'It often contains pawns and entry points near the enemy king.', 'Its number gives every rook extra movement powers.', 'The initial pawn and king arrangement creates practical targets there.', 'A rook’s movement rules are the same on every rank.')),
    ('Do not claim a complete king fence when pawns block the rook’s rank.', 'After an invasion, inspect each target’s defenders before capturing.'))

GUIDES['concentration'] = _guide('concentration', (107, 108),
    ('Concentrate on a target that cannot easily escape.', 'The values and capture order determine whether pressure wins material.', 'A queen on d4 adds an attacker and blocks the d-pawn’s advance.'),
    """The knight on c3 attacks d5, and Black's queen on d8 protects that pawn. An immediate Nxd5 would allow Qxd5, giving a knight for a pawn. Qd4 changes the relationship: White's queen also attacks d5 and protects a knight that lands there. It occupies d4, so Black cannot simply push the pawn onto that occupied square. In the illustrative line Black moves the queen to d6 and White plays Nxd5. A careless Qxd5 would then allow Qxd5+, costing Black a queen for the knight. Black was not compelled to choose Qd6 or permit this exact capture; checks and queen activity require attention. The exercise asks for the specified concentration on d4, not a claim that a raw two-against-one count proves a forced win against every reply.""",
    """Draw the sequence after Nxd5 before Qd4, then draw it after Qd4. Keep a material ledger that includes the capturing pieces themselves. Also compare Qd3, which attacks d5 but does not block the pawn's advance to d4. These moves have related purposes but different geometry. Finally inspect Ne4: a knight on e4 does not attack d5 at all, so moving there actually removes an existing attacker rather than adding one.""",
    ('Qd4', 'Qd6', 'Nxd5'),
    ('The knight alone cannot profitably capture a queen-defended pawn.', 'The queen adds pressure, protects a knight on d5 and stops the pawn advancing to d4.', 'Black keeps a queen defence of d5; this is an illustrative reply, not forced.', 'The knight captures with queen support. Qxd5 would now lose the black queen after Qxd5+.'),
    (('Why is Nxd5 unsafe before the queen joins?', 'Black can take that knight with Qxd5.', 'A knight cannot capture a pawn diagonally.', 'The knight’s move is legal but loses material to the defender.', 'Knights capture using their normal jumping movement.'),
     ('Does a knight on e4 attack d5?', 'No.', 'Yes.', 'Its destinations include d6 and c5, but not d5.', 'Trace the L-shaped move rather than estimating nearby squares.')),
    ('Do not replace a capture calculation with an attacker tally.', 'Check that a supposed extra attacker actually attacks the target square.'))

GUIDES['deflection'] = _guide('deflection', (108, 110),
    ('Deflection makes a defender abandon a useful duty.', 'Name the duty and its payoff before offering material.', 'The opponent may decline the offer, so calculate that branch too.'),
    """The knight on f6 protects g8, which prevents an immediate safe queen promotion. Ne4+ is a purposeful offer because it both checks the black king and attacks that defending knight. If Black accepts with Nxe4, the defender is drawn off f6 and can no longer capture a new queen on g8. White then promotes. The check does not force Nxe4: Black has legal king moves. After a king retreat such as Kf1, White can instead capture the defender with Nxf6, leaving the pawn ready to promote later. That branch uses removal rather than displacement. The shared aim is to eliminate the knight's control of g8. A random capture of an undefended knight would win material but would not teach why this particular defender's old square mattered.""",
    """Begin by trying g8=Q and answering Nxg8 so that you can see the defender's duty. Then reset and examine Ne4+ in two branches: acceptance by the knight and refusal by the king. Keep the promotion square visible throughout the calculation. As a transfer exercise, move the black knight to a square that does not control g8. The reason for the deflection disappears, so a direct promotion may become sufficient.""",
    ('Ne4+', 'Nxe4', 'g8=Q'),
    ('The f6-knight guards promotion on g8; an immediate queen would be captured.', 'The white knight checks and offers to draw that defender away.', 'Black accepts the offer. A king move was also legal and needs its own calculation.', 'The pawn promotes because the knight on e4 no longer controls g8.'),
    (('What precise duty does the knight on f6 perform?', 'It controls the pawn’s promotion square g8.', 'It prevents the white king from moving anywhere.', 'The promotion square is the tactical target affected by the knight’s departure.', 'The king still has legal moves; the relevant duty is much more specific.'),
     ('Is Nxe4 the only legal answer to Ne4+?', 'No; Black can also move the king.', 'Yes; every offered piece must be captured.', 'After a king move, Nxf6 is the alternative removal of the defender.', 'An offered sacrifice does not make acceptance compulsory.')),
    ('Name what the defender protects; “it stands near the king” is not enough.', 'Do not call an optional recapture forced when legal king replies exist.'))

GUIDES['attraction'] = _guide('attraction', (108, 110),
    ('Attraction brings a piece onto an exploitable square.', 'The bait capture must be legal and the payoff calculated.', 'Count the whole sacrifice, including later recaptures.'),
    """The king on g8 has its own queen on f8, rook on f7 and pawn on g7. Rh8+ checks along the eighth rank. Kxh8 is the only legal reply: f8, f7 and g7 are occupied by Black, h7 is controlled by the rook, and no other piece can capture or interpose between adjacent h8 and g8. Crucially, the rook on h8 is not protected by a white piece, so the king's capture is legal. After the king is attracted to h8, Ng6+ attacks it and the queen on f8. Black must answer check, and Nxf8 captures the queen. The knight may be recaptured afterwards by the remaining rook or king. This is still a purposeful material transaction, but the whole resulting queen-versus-rook-and-pawns position must be evaluated rather than declaring victory at the moment of the fork.""",
    """Before moving the rook, list every black answer to check and rule them out one by one. After Kxh8, trace the knight's two target squares h8 and f8. Compare Ng6 played immediately: with the king still on g8 it would not be check, and Black could move the queen. Finally count both rook and knight as potential costs, rather than counting only the rook offered on the first move.""",
    ('Rh8+', 'Kxh8', 'Ng6+', 'Kg8', 'Nxf8'),
    ('White needs the king on h8 before the knight fork becomes a checking fork.', 'The rook offers legal bait beside the king.', 'This capture is the only legal response; the king has been attracted to the target square.', 'The knight now checks h8 and attacks the queen on f8.', 'The king must escape check. Kg8 is an example of an escape.', 'White captures the queen; inspect a possible recapture of the knight before evaluating what remains.'),
    (('If an offered queen on e8 is protected so Kxe8 is illegal, can that offer attract the king onto e8?', 'No; the king cannot legally occupy e8 by capturing that queen.', 'Yes; every check beside a king attracts it onto the checking square.', 'Attraction onto a square requires that the piece actually be able to occupy it.', 'A forbidden capture cannot form the required bait-taking sequence.'),
     ('Why is Ng6 more forcing after Kxh8?', 'It now checks the king as well as attacking the queen.', 'Knights gain extra powers after a sacrifice.', 'The king’s changed square creates the checking fork geometry.', 'The knight’s movement rules are unchanged.')),
    ('Do not describe an illegal king capture as poisoned bait.', 'A queen won during a combination does not excuse ignoring later recaptures and remaining material.'))

GUIDES['many-sided-threats'] = _guide('many-sided-threats', (110, 111),
    ('Two different threats can overload the opponent’s response.', 'A mate threat and a material threat need separate proof.', 'Search for a single defensive move that might answer both.'),
    """Qh5 does two jobs on this board. It attacks the bishop on a5 across the fifth rank, and it threatens Qxf7 mate with the c4-bishop's support. Black's rook on h8 occupies an important king escape square. After g6, the mating diagonal is blocked but Qxa5 captures the bishop. After a bishop move such as Bb6, the material target escapes but Qxf7 remains mate. The bishop travels on dark squares and cannot interpose on light g6 or protect light f7. These branches show why the threats require different defensive actions. They do not replace checking counterchecks and captures: in another position a bishop move with check, an attack on the queen or an escape square for the king could meet both threats indirectly. Always test those possibilities before announcing a forced gain.""",
    """Write the two threatened continuations before moving the queen. In each defensive branch cross out only the threat that has actually been met. Compare the geometry with an ordinary knight fork: here the queen threatens a capture and a mating capture, using different lines and the bishop's protection. Then remove the rook on h8 and recheck Qxf7: an escape on h8 can change the claimed mate, so that apparently incidental rook matters.""",
    ('Qh5', 'g6', 'Qxa5'),
    ('White can threaten the a5-bishop and a protected mating capture on f7.', 'The queen attacks a5 along the rank and f7 along the diagonal.', 'Black blocks the mating diagonal and attacks the queen, but the bishop remains a target.', 'White captures the bishop while moving the queen out of the pawn attack.'),
    (('Which threats does Qh5 create here?', 'Qxf7 mate and Qxa5.', 'Only an attack on the bishop.', 'The bishop on c4 protects f7 while the queen also attacks a5.', 'The king threat is a separate, concrete continuation.'),
     ('What must you search for before trusting two threats?', 'A countercheck, capture or defence that solves both at once.', 'Nothing; two threats always win.', 'A single forcing reply can sometimes interrupt both threats.', 'The label does not prove the opponent lacks a combined defence.')),
    ('Check all lines, blockers and king escapes before claiming a double threat.', 'Do not use a target defended by the king as if it were a free material prize.'))

GUIDES['open-lines'] = _guide('open-lines', (111, 113),
    ('A pawn leaving a file can activate a rook behind it.', 'An open line needs an entry or target to become valuable.', 'Opening a line may help the opponent as well as you.'),
    """The d4-pawn stands between the rook on d1 and the upper part of the d-file. Capturing e5 removes that own blocker from the file. The rook can now travel as far as d8 if the intervening squares remain clear. Pushing d5 would keep the pawn in front of the rook, so it would not achieve the same line-opening task. The worked line gives Black Kb7 as an illustrative reply and then shows Rd7+, using the cleared file for an entry with check. That king reply is not forced, and the example is not a proof of an immediate material win. In a full middlegame you should identify the enemy pawn, queen or king position the line will reach, and check whether an opposing rook can exploit the opening first. Opening a road without a useful destination may simply waste time.""",
    """Trace the d-file before and after dxe5 and name the first occupied square in each version. Then compare d5: the pawn has advanced, but the rook's line is still obstructed. Add a hostile rook on the file and calculate exchanges before opening it. Finally consider a bishop diagonal cleared by a pawn capture; the same method applies even though the route runs diagonally rather than vertically.""",
    ('dxe5', 'Kb7', 'Rd7+', 'Kc6'),
    ('The rook’s own pawn blocks the d-file.', 'The pawn captures away from the file, leaving a clear rook road.', 'Black chooses a king move; it is an illustrative response rather than forced.', 'The rook uses the newly clear file to enter with check.', 'The king escapes the checked rank, showing how activity creates concrete replies.'),
    (('Why does dxe5 open the d-file while d5 does not?', 'The capture removes the white pawn from the file.', 'A capture always opens every nearby file.', 'Only the line vacated by the pawn is cleared in this way.', 'Other lines may remain blocked or become newly obstructed.'),
     ('What should you identify before opening a line?', 'The piece that will use it and the useful target or entry.', 'Only whether a pawn can be captured.', 'A purposeful opening improves a piece’s route towards something relevant.', 'A legal capture can open a line the opponent uses more effectively.')),
    ('A pawn advance along a file can leave the same rook obstruction in place.', 'An open line is not automatically favourable; check which side can occupy it.'))

GUIDES['block-lines'] = _guide('block-lines', (113, 114),
    ('Interposition can answer a distant sliding-piece check.', 'The blocker may become pinned to the king.', 'Check whether the opponent can profitably capture the blocker.'),
    """White's king on e1 is checked by the rook on e8, with a clear e-file between them. Ne2 inserts a knight into that line. The king protects e2, so Rxe2+ could be answered by Kxe2, trading Black's rook for a knight. The block therefore has a concrete safety reason rather than merely placing something in the rook's path. After Ne2 the knight is absolutely pinned: it cannot jump away if doing so would uncover the rook check. In the line Black makes Kb7, then White's Kd2 leaves the e-file and releases the knight from that pin. Black's move is illustrative, not forced. This demonstrates two stages of defence: first answer the immediate check, then improve the lasting arrangement. Against a knight check or an adjacent rook check, no interposition square may exist.""",
    """Enumerate all squares between e8 and e1, then identify which can actually be reached by the c3-knight. Verify that Ne2 leaves the king safe. Next try moving the knight away before moving the king: the resulting rook check shows why that jump is illegal. Finally move the king to d2 and try again. This makes the difference between a legal block and a permanently free piece visible on the board.""",
    ('Ne2', 'Kb7', 'Kd2'),
    ('The rook checks down a clear file, so White must answer king danger.', 'The knight interposes and is protected by the king, but becomes pinned.', 'Black makes an illustrative king move rather than sacrificing the rook for the knight.', 'White leaves the pin file, so future knight moves no longer expose rook check.'),
    (('Why can Rxe2+ be answered by Kxe2 here?', 'The white king protects the blocking knight on e2.', 'Rooks may never capture knights.', 'The king’s recapture would leave it safe from other black attacks.', 'A rook may capture a knight, but the resulting exchange can be poor.'),
     ('Can every check be blocked?', 'No; a knight check or adjacent sliding check may have no interposition square.', 'Yes; any piece can always stand in the way.', 'A block needs a genuine square between a line attacker and the king.', 'Not every checking attack has an intervening line segment.')),
    ('A defended blocker can still be pinned and restricted.', 'Do not block an attack when a simpler capture or stronger defence is available without comparing them.'))

GUIDES['breakthrough'] = _guide('breakthrough', (114, 116),
    ('A breakthrough can sacrifice pawns to create a passer.', 'Calculate both captures of the central pawn.', 'The distant king must be unable to stop the surviving pawn.'),
    """The first move b6 offers a pawn to both a7 and c7. Its purpose is to divert one outside pawn and prepare a second sacrifice on the other side. After cxb6, a6 offers another pawn to b7; bxa6 leaves c6 with a clear route through c7 to c8. After axb6, the corresponding follow-up is c6, and bxc6 leaves a6 as the surviving passer. The middle move cannot be memorized without those branches because choosing the wrong second pawn can close the route. Black may also decline a capture, which requires checking the pawn's advance or capture options rather than assuming acceptance. The kings' placement matters: a nearby defender could stop the new passer even after the pawn geometry succeeds. This board keeps both kings far from the decisive promotion route.""",
    """Play both capture branches until one white pawn has an unobstructed promotion path. Name every black pawn's new square, especially the pawn diverted from b7. Then compare the immediate outside pushes a6 and c6; Black can capture them without permitting the same forced second diversion. For transfer practice move the black king several squares closer and count whether it reaches the route in time before calling the breakthrough winning.""",
    ('b6', 'cxb6', 'a6', 'bxa6', 'c6'),
    ('Three pawns face three pawns; White seeks a surviving passer, not a simple first capture.', 'The middle pawn offers itself to divert an outside pawn.', 'Black accepts from c7, vacating the c-file.', 'White offers the a-pawn to draw b7 away from that file.', 'Black accepts the second sacrifice, leaving no black pawn on the c-file.', 'The remaining c-pawn now has a clear promotion route; the black king is too distant to catch it.'),
    (('After b6 cxb6, what is the key second move?', 'a6.', 'c6 immediately.', 'a6 draws the b7-pawn away so the c-pawn will have a clear route.', 'The pawn on b7 would otherwise remain available to stop the intended route.'),
     ('What extra factor can spoil a geometrically correct breakthrough?', 'The enemy king reaching the surviving passer in time.', 'The fact that two white pawns were sacrificed.', 'A passer still needs enough time and a safe route to promote.', 'The sacrifices are intentional; the final passer is the payoff.')),
    ('Do not judge the combination by the first sacrificed pawn.', 'A passed pawn is not automatically an unstoppable pawn; count king moves.'))

GUIDES['tempo'] = _guide('tempo', (95, 96),
    ('A useful threat can gain time for development or space.', 'The opponent must still be checked for forcing counterplay.', 'Moving the same piece twice is not always a wasted tempo.'),
    """The c2-pawn can advance to c3 and attack the bishop on b4. The pawn on d2 blocks the bishop's diagonal to the white king, so White is not overlooking check. In the line Black saves the bishop with Bc5 and White develops Nf3. That is the sense in which the pawn move can gain time: it makes progress while asking the opponent to address an attacked piece. It does not grant White two consecutive turns, and Black might answer a threat with a capture, exchange or stronger threat instead of a retreat. Also ask whether c3 is useful to your own position; chasing a bishop onto a better diagonal can help the opponent. The source's early queen chase illustrates the same principle through development: a new knight attacks the queen while improving itself, making the queen spend another move.""",
    """After c3 list the bishop's legal replies and compare their activity rather than treating every retreat as identical. Then identify what White gained besides the attack: c3 occupies space and supports a future central advance. For a full opening example replay e4 d5 exd5 Qxd5 Nc3 and a queen retreat, followed by White developing another piece. Count developed units, not simply total moves played.""",
    ('c3', 'Bc5', 'Nf3'),
    ('The d2-pawn shields the king, leaving White free to attack the bishop.', 'The pawn advances with a threat against b4.', 'Black preserves the bishop by moving it; this is one reasonable response.', 'White uses the next turn to develop another piece, showing a practical use of the earlier tempo.'),
    (('Does gaining a tempo mean taking two turns in a row?', 'No; it means using a move usefully while the opponent must attend to a threat.', 'Yes; the opponent loses the right to move.', 'The move order is unchanged; the relative usefulness of moves changes.', 'Chess still alternates turns normally.'),
     ('Is moving one piece twice always bad?', 'No; a forcing or necessary second move can be justified.', 'Yes; it always loses a tempo.', 'Calculate the purpose and result instead of applying a move-count slogan.', 'Necessary defence, captures and tactics can justify repeated moves.')),
    ('An attack is not automatically a useful tempo if it improves the opponent’s piece.', 'Do not assume the attacked piece must retreat; search captures and counterchecks too.'))

GUIDES['zugzwang'] = _guide('zugzwang', (116, 118),
    ('The obligation to move can concede important squares.', 'A reserve pawn move can preserve a useful king arrangement.', 'Opposition matters when it supports an actual pawn-conversion plan.'),
    """The kings on e5 and e7 face each other across e6. White's central pawn on e4 follows its king, while h2 supplies a waiting move. Either h3 or h4 keeps the white king in place and makes Black choose a king move. Black cannot enter d6, e6 or f6 because White's king controls them. After the illustrative Kd7, White enters on f6 and begins escorting the central pawn. This is preparation with reserve tempi, not a clean win-versus-draw comparison: the extra h-pawn means White already has additional winning resources. With that pawn removed, the same central king-and-pawn placement is drawn with White to move and won with Black to move. The additional worked examples compare those cases explicitly. It would be misleading to use only a distant h-pawn and say the same opposition guarantees victory; a defending king may reach the rook-pawn corner. Zugzwang also differs from a poor position with no attractive move: the comparison is with being able to pass, and the legal obligation must cause the relevant concession.""",
    """Before spending a reserve pawn move, identify the square your king wants and the opponent's restricted replies. Compare h3 and h4: both meet this exercise, but one-step moves can preserve an additional reserve tempo for later positions. Then remove the e4-pawn and reconsider the purpose of penetration. Finally practise a real triangulation, where a king manoeuvre returns the board to the same arrangement with the other player to move.""",
    ('h3', 'Kd7', 'Kf6', 'Ke8', 'e5'),
    ('White can preserve opposition without moving the king by using its h-pawn.', 'The waiting move hands the move to Black while keeping the central arrangement.', 'Black chooses a side; the king cannot enter White’s controlled sixth-rank squares.', 'White penetrates on the other side, giving the opposition a concrete purpose.', 'Black retreats towards the promotion area; this is an illustrative defensive route.', 'The central pawn advances with its king ahead and nearby; further conversion still needs care.'),
    (('Do both h3 and h4 satisfy the reserve-tempo task?', 'Yes; both keep the king on e5 and pass the turn.', 'No; only a two-square pawn move can pass a tempo.', 'Either legal pawn advance changes the side to move without moving the king.', 'A one-square move uses a turn just as a two-square move does.'),
     ('How does zugzwang differ from stalemate?', 'In zugzwang legal moves exist but the obligation hurts; stalemate has no legal move and no check.', 'Both mean the player has no legal move.', 'The existence of legal moves is the key distinction.', 'Stalemate is a drawn terminal position; zugzwang is not.')),
    ('Opposition is a tool for a concrete objective, not a guarantee that every rook-pawn ending wins.', 'Do not spend all spare pawn moves without considering which tempos you may need later.'))

GUIDES['counterplan'] = _guide('counterplan', (118, 119),
    ('A useful move can advance your plan while obstructing the opponent’s.', 'Equal-length routes can differ in the squares they deny.', 'Account for the opponent’s intended route before choosing yours.'),
    """White wants to remove h7 and promote h6. Black's king wants to travel from f3 through e4 and f5, reaching the promotion battle before it is too late. Ke5 approaches the h-pawn while controlling e4, so the planned black king step is illegal. Compare Ke6: it also approaches h7, but no longer denies e4. This is a concrete difference in counterplay, not a preference for a prettier king route. In the worked line Black uses Kg4, White continues Kf6, Black chooses Kf4 and White reaches Kg7. Those king replies are illustrative rather than forced. White's earlier obstruction costs the defender valuable time. The general habit applies to middlegames too: when two developing moves both seem natural, compare what each one prevents in the opponent's plan as well as what it improves for you.""",
    """Mark Black's intended route before choosing a white move. After Ke5, test Ke4 and identify the white king attack that forbids it. Then reset and try Ke6 Ke4, noting how the opponent's route remains available. Count the travel time to the h-pawn in both cases. This exercise asks for the specific route-obstructing square e5; it does not claim that every other legal king move immediately loses without further calculation.""",
    ('Ke5', 'Kg4', 'Kf6', 'Kf4', 'Kg7'),
    ('Both kings have plans involving the h-pawn; their routes interact.', 'White approaches h7 and prevents the intended Ke4 route.', 'Black selects another route because e4 is attacked.', 'White continues towards the target while the defender has been diverted.', 'Black moves closer by a longer path; this is illustrative.', 'White reaches the pawn’s neighbourhood ahead of that defensive route.'),
    (('What extra job does Ke5 perform compared with Ke6?', 'It controls e4 and obstructs the opposing king’s route.', 'It gives check to the king on f3.', 'The important effect is prevention of a future king step.', 'The kings are not adjacent after Ke5, so it is not check.'),
     ('What should break a tie between two natural moves?', 'Compare how they affect the opponent’s threats and intended replies.', 'Choose without considering the opponent’s plan.', 'A move’s preventive effect can be as important as its direct improvement.', 'Ignoring resistance can turn a sensible-looking plan into a failed race.')),
    ('Do not evaluate your route while imagining the opponent stands still.', 'A quiet move can counter a plan by controlling a key square without making a direct threat.'))

